	if found {
		if h.Buf.Settings["matchbraceleft"].(bool) {
			if left {
				h.Cursor.GotoLoc(matchingBrace)
			} else {
				h.Cursor.GotoLoc(matchingBrace.Move(1, h.Buf))
			}
		} else {
			h.Cursor.GotoLoc(matchingBrace)
		}
		h.Relocate()
		return true
	}
	return false
}

